CREATE TABLE IF NOT EXISTS print_order (
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "owner_id" uuid DEFAULT auth_uid() NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
  "status" text DEFAULT 'draft' NOT NULL CHECK ("status" IN ('draft', 'quoting', 'quote_failed', 'quoted', 'opening', 'open_failed', 'awaiting_payment', 'checking', 'placing', 'recording', 'placed', 'vendor_checking', 'alerting', 'attention')),
  "created_at" portable_timestamp DEFAULT now() NOT NULL,
  "title" text NOT NULL CHECK (char_length(title) > 0 AND char_length(title) <= 120),
  "stock" text NOT NULL CHECK (stock IN ('gloss', 'mohawk')),
  "cards" integer NOT NULL CHECK (cards >= 1 AND cards <= 100),
  "country" text NOT NULL CHECK (country IN ('BR', 'AR', 'IL', 'US', 'GB', 'CN')),
  "delivery" json CONSTRAINT "print_order_delivery_type" CHECK ("delivery" IS NULL OR public.portable_json_valid("delivery") IS TRUE),
  "artwork" json CONSTRAINT "print_order_artwork_type" CHECK ("artwork" IS NULL OR public.portable_json_valid("artwork") IS TRUE),
  "item" integer,
  "shipping" integer,
  "total" integer,
  "cost" integer,
  "currency" text,
  "sku" text,
  "shipping_method" text,
  "session_id" text,
  "checkout_url" text,
  "checks" integer DEFAULT 0 NOT NULL,
  "payment_state" text,
  "payment_intent" text,
  "customer_email" text,
  "paid_at" portable_timestamp,
  "vendor_order_id" text,
  "vendor_state" text,
  "vendor_checks" integer DEFAULT 0 NOT NULL,
  "failure" text,
  "txid" BIGINT DEFAULT pg_current_xact_id()::text::bigint,
  "scope_id" TEXT GENERATED ALWAYS AS ('user:' || "owner_id") STORED NOT NULL
);

